// Human labels for scripts and languages, generated by the harvester
// (to_dataset.py write_label_maps) from gflanguages, so the frontend renders
// readable names without shipping gftools. See the language-support task.
import languagesRaw from "@/data/languages.json";
import scriptsRaw from "@/data/scripts.json";

export interface LanguageMeta {
  name: string;
  script: string;
  population: number;
}

const scripts = scriptsRaw as Record<string, string>;
const languages = languagesRaw as Record<string, LanguageMeta>;

// Google Fonts' website shows a curated MAJOR-language subset; population>=5M
// reproduces it cleanly. The UI defaults to these, with a "show all" expander.
export const MAJOR_LANG_POPULATION = 5_000_000;

/** "Latn" -> "Latin"; unknown codes pass through unchanged. */
export function scriptLabel(code: string): string {
  return scripts[code] ?? code;
}

/** "en_Latn" -> "English"; unknown ids pass through unchanged. */
export function languageLabel(id: string): string {
  return languages[id]?.name ?? id;
}

export function languagePopulation(id: string): number {
  return languages[id]?.population ?? 0;
}

/** Split lang ids into major (>=5M speakers) and the rest, each name-sorted. */
export function splitLanguages(ids: string[]): {
  major: string[];
  minor: string[];
} {
  const major: string[] = [];
  const minor: string[] = [];
  for (const id of ids) {
    if (languagePopulation(id) >= MAJOR_LANG_POPULATION) major.push(id);
    else minor.push(id);
  }
  const byName = (a: string, b: string) =>
    languageLabel(a).localeCompare(languageLabel(b));
  return { major: major.sort(byName), minor: minor.sort(byName) };
}
